package org.telegram.messenger;

import android.graphics.*;
import dalvik.system.DexClassLoader;
import org.json.*;
import org.telegram.messenger.devgram.nodes.*;
import org.telegram.ui.Components.devgram.frame.*;
import java.io.*;
import java.net.*;
import java.util.*;
import java.util.concurrent.*;

/** Independently installed, hash-verified node code from the DevGram catalog. */
public final class DevGramNodePackages {
    public interface Callback<T>{void done(T result,String error);}
    private static final ExecutorService IO=Executors.newSingleThreadExecutor(r->{Thread t=new Thread(r,"devgram-node-packages");t.setDaemon(true);return t;});
    private static final ConcurrentHashMap<Integer,Node> nodes=new ConcurrentHashMap<>();private static final ConcurrentHashMap<String,Integer> versions=new ConcurrentHashMap<>();private static final HashMap<String,Set<Integer>> owned=new HashMap<>();private static final Set<Integer> disabled=ConcurrentHashMap.newKeySet();
    private static volatile boolean loading,loaded;private static volatile int epoch;private static NodePackageFiles files;
    private DevGramNodePackages(){}
    public static boolean installed(int type){return nodes.containsKey(type)&&!disabled.contains(type);}
    public static int epoch(){return epoch;}public static int version(String pkg){return versions.getOrDefault(pkg,0);}
    public static synchronized void ensure(){if(loading||loaded)return;loading=true;IO.execute(()->{try{files=new NodePackageFiles(ApplicationLoader.applicationContext.getFilesDir());for(NodePackageFiles.Entry entry:files.entries())try{activate(entry,load(entry));}catch(Throwable error){FileLog.e(error);}}catch(Exception error){FileLog.e(error);}finally{loaded=true;loading=false;notifyChanged();}});}
    private static void ready()throws IOException{if(files==null)files=new NodePackageFiles(ApplicationLoader.applicationContext.getFilesDir());}
    public static void catalog(Callback<List<NodePackageFiles.Entry>> callback){ensure();IO.execute(()->{List<NodePackageFiles.Entry> result=null;String error=null;try{JSONObject catalog=new JSONObject(new String(get("studio/node-packages",1024*1024),"UTF-8"));JSONArray packages=catalog.getJSONArray("packages");if(packages.length()>100)throw new IOException();result=new ArrayList<>();HashSet<String> ids=new HashSet<>();for(int i=0;i<packages.length();i++){NodePackageFiles.Entry entry=new NodePackageFiles.Entry(packages.getJSONObject(i));if(!ids.add(entry.pkg))throw new IOException();validateDefinitions(entry);result.add(entry);}for(NodePackageFiles.Entry installed:files.entries())if(!ids.contains(installed.pkg))result.add(installed);}catch(Exception failure){FileLog.e(failure);error="node_catalog_failed";try{ready();result=files.entries();}catch(Exception ignored){}}List<NodePackageFiles.Entry> answer=result;String failure=error;AndroidUtilities.runOnUIThread(()->callback.done(answer,failure));});}
    public static void install(NodePackageFiles.Entry entry,Callback<Boolean> callback){ensure();IO.execute(()->{boolean success=false;try{ready();validateDefinitions(entry);byte[] code=get("studio/node-packages/file/"+entry.file,NodePackageFiles.MAX_BYTES);files.stage(entry,code);Map<Integer,Node> loadedNodes=load(entry);files.commit(entry);activate(entry,loadedNodes);success=true;notifyChanged();}catch(Throwable error){FileLog.e(error);}boolean answer=success;AndroidUtilities.runOnUIThread(()->callback.done(answer,answer?null:"node_install_failed"));});}
    public static void remove(NodePackageFiles.Entry entry,Callback<Boolean> callback){ensure();IO.execute(()->{boolean success=false;try{ready();files.remove(entry.pkg);Set<Integer> removed=owned.remove(entry.pkg);if(removed!=null)for(int type:removed)nodes.remove(type);versions.remove(entry.pkg);epoch++;disabled.clear();success=true;notifyChanged();}catch(Exception error){FileLog.e(error);}boolean answer=success;AndroidUtilities.runOnUIThread(()->callback.done(answer,answer?null:"node_remove_failed"));});}
    private static void validateDefinitions(NodePackageFiles.Entry entry)throws Exception{JSONArray definitions=entry.json().getJSONArray("nodes");HashSet<Integer> seen=new HashSet<>();for(int i=0;i<definitions.length();i++){JSONObject definition=definitions.getJSONObject(i);if(!seen.add(definition.getInt("type")))throw new IOException("node_collision");String id=definition.getString("id");if(definition.getInt("type")!=FramePackageTypes.typeOf(id))throw new IOException("node_type");JSONArray knobs=definition.getJSONArray("knobs");if(knobs.length()>32)throw new IOException("node_knobs");}}
    private static Map<Integer,Node> load(NodePackageFiles.Entry entry)throws Exception{
        File file=files.file(entry);if(!NodePackageFiles.hash(NodePackageFiles.read(file,NodePackageFiles.MAX_BYTES)).equals(entry.sha256))throw new IOException("node_hash");if(!file.setReadOnly())throw new IOException("node_readonly");File optimized=new File(ApplicationLoader.applicationContext.getCodeCacheDir(),"devgram-nodes");if(!optimized.isDirectory()&&!optimized.mkdirs())throw new IOException("node_cache");
        Object instance=new DexClassLoader(file.getPath(),optimized.getPath(),null,DevGramNodePackages.class.getClassLoader()).loadClass(entry.main).getDeclaredConstructor().newInstance();if(!(instance instanceof NodePackage))throw new IOException("node_entry");Node[] code=((NodePackage)instance).nodes();JSONArray definitions=entry.json().getJSONArray("nodes");if(code==null||code.length!=definitions.length())throw new IOException("node_count");HashMap<Integer,JSONObject> expected=new HashMap<>();for(int i=0;i<definitions.length();i++)expected.put(definitions.getJSONObject(i).getInt("type"),definitions.getJSONObject(i));Map<Integer,Node> result=new HashMap<>();for(Node node:code){if(node==null)throw new IOException();int type=FramePackageTypes.typeOf(node.id());JSONObject definition=expected.get(type);if(definition==null||!definition.getString("id").equals(node.id())||node.category()!=definition.optInt("category",7)||result.containsKey(type))throw new IOException("node_descriptor");Knob[] knobs=node.knobs();JSONArray declared=definition.getJSONArray("knobs");if(knobs==null||knobs.length!=declared.length())throw new IOException("node_knobs");for(int i=0;i<knobs.length;i++){JSONObject value=declared.getJSONObject(i);Knob knob=knobs[i];if(knob==null||knob.kind!=value.getInt("kind")||knob.min!=value.getInt("min")||knob.max!=value.getInt("max")||knob.start!=value.getInt("default"))throw new IOException("node_knob_schema");}result.put(type,node);}return result;
    }
    private static void activate(NodePackageFiles.Entry entry,Map<Integer,Node> code)throws Exception{JSONArray definitions=entry.json().getJSONArray("nodes");AndroidUtilities.runOnUIThread(()->{try{for(int i=0;i<definitions.length();i++)FramePackageTypes.register(definitions.getJSONObject(i),true);}catch(Exception error){FileLog.e(error);}});Set<Integer> previous=owned.put(entry.pkg,new HashSet<>(code.keySet()));if(previous!=null)for(int type:previous)nodes.remove(type);nodes.putAll(code);versions.put(entry.pkg,entry.version);disabled.clear();epoch++;}
    private static void notifyChanged(){AndroidUtilities.runOnUIThread(DevGramProfilePolicy::changed);}
    private static byte[] get(String path,int max)throws IOException{HttpURLConnection connection=(HttpURLConnection)new URL(DevGramProfilePolicy.BASE+path).openConnection();try{connection.setInstanceFollowRedirects(false);connection.setConnectTimeout(12000);connection.setReadTimeout(20000);if(connection.getResponseCode()!=200||connection.getContentLengthLong()>max)throw new IOException("node_http");try(InputStream input=connection.getInputStream()){return NodePackageFiles.read(input,max);}}finally{connection.disconnect();}}
    public static boolean has(List<FrameSpec.Effect> effects){for(FrameSpec.Effect effect:effects)if(nodes.containsKey(effect.type)&&!disabled.contains(effect.type))return true;return false;}
    /** Input belongs to ImageReceiver. Only package-owned copies can be recycled or modified. */
    public static Bitmap process(Bitmap source,List<FrameSpec.Effect> effects){
        if(!has(effects)||source==null||source.isRecycled())return source;Bitmap current=null;
        try{current=source.copy(Bitmap.Config.ARGB_8888,true);if(current==null)return source;for(FrameSpec.Effect effect:effects){Node node=nodes.get(effect.type);if(node==null||disabled.contains(effect.type))continue;try{Bitmap filtered=node.filter(current,effect.knobs.clone());if(filtered!=null&&filtered!=current){if(filtered.isRecycled()||filtered.getWidth()!=source.getWidth()||filtered.getHeight()!=source.getHeight())throw new IllegalArgumentException("node_bitmap");current.recycle();current=filtered;}Bitmap base=current;Bitmap pass=Bitmap.createBitmap(base.getWidth(),base.getHeight(),Bitmap.Config.ARGB_8888);Canvas canvas=new Canvas(pass);canvas.drawBitmap(base,0,0,null);RenderContext context=new RenderContext(){public int alpha(){return 255;}public int[] knobs(){return effect.knobs.clone();}public Bitmap image(){return base;}public void drawImage(Bitmap bitmap,Paint paint){if(bitmap!=null&&!bitmap.isRecycled())canvas.drawBitmap(bitmap,null,new Rect(0,0,pass.getWidth(),pass.getHeight()),paint);}};try{node.render(context);base.recycle();current=pass;}finally{if(current!=pass&&!pass.isRecycled())pass.recycle();}}catch(Throwable error){disabled.add(effect.type);FileLog.e(error);}}
            return current;
        }catch(OutOfMemoryError pressure){if(current!=null&&current!=source&&!current.isRecycled())current.recycle();return source;}
    }
}
